create or replace function public.crm_experiment_guardrail_status(p_experiment_id uuid)
returns jsonb language sql security invoker stable set search_path=public as $$
with variants as (select id,name from public.crm_experiment_variants where experiment_id=p_experiment_id), stats as (select v.id,v.name,count(e.id)::integer exposures,count(o.id) filter(where lower(o.outcome) in('converted','conversion','recovered','recovery'))::integer positive from variants v left join public.crm_experiment_exposures e on e.variant_id=v.id left join public.crm_experiment_outcomes o on o.exposure_id=e.id group by v.id,v.name), guard as (select * from public.crm_experiment_guardrails where experiment_id=p_experiment_id and enabled), metric as (select coalesce(jsonb_agg(jsonb_build_object('metric',g.metric_name,'type',g.metric_type,'minimum_sample_size',g.min_sample_size,'max_regression',g.max_regression,'status',case when coalesce((select max(exposures) from stats),0)>=g.min_sample_size then 'sample_ready' else 'collecting' end) order by g.metric_name),'[]'::jsonb) data from guard g) select jsonb_build_object('experiment_id',p_experiment_id,'variant_stats',coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from stats s),'[]'::jsonb),'guardrails',(select data from metric),'winner_eligible',coalesce((select max(exposures) from stats),0)>=coalesce((select max(min_sample_size) from guard),100),'generated_at',now());
$$;
revoke all on function public.crm_experiment_guardrail_status(uuid) from public,anon;
grant execute on function public.crm_experiment_guardrail_status(uuid) to authenticated;
